const cmd = String.raw`env -u OPENAI_API_KEY -u ANTHROPIC_API_KEY node --input-type=module - <<'NODE'
import fs from 'node:fs';
import {checkPublication} from './.assessment-cache/debate-268-check-publication-draft.mjs';
const p=JSON.parse(fs.readFileSync('docs/assessment-production/standalone-debates-v1/debate-268/publication/input-bundle.json'));
const ledger=JSON.parse(fs.readFileSync(p.ledgerPath));
const scores=JSON.parse(fs.readFileSync(p.scorePath));
const c=structuredClone(p.lockedCandidateSkeleton);
const clean=s=>String(s).replace(/[.!?]/g,'').replace(/\s+/g,' ').trim();
const ws=s=>String(s).trim().split(/\s+/).filter(Boolean);
const scoreMap=new Map(scores.sections.flatMap(sec=>['pro','con'].flatMap(side=>sec.sides[side].moves.map(m=>[m.moveId,m.score]))));
function desc(m){let s=clean(m.claim)+' '+clean(m.inference);return s+'.'}
function crit(m,i){
 const ds=Object.entries(m.finalDimensions),hi=ds.slice().sort((a,b)=>b[1].value-a[1].value)[0],lo=ds.slice().sort((a,b)=>a[1].value-b[1].value)[0];
 let b=[
  clean(m.claim)+' The strongest dimension is '+hi[0].replace(/([A-Z])/g,' $1').toLowerCase()+', because '+clean(hi[1].rationale),
  clean(lo[1].rationale)+' The central weakness concerns '+clean(m.warrant)+', which limits how far this move can establish its conclusion',
  clean(m.burdenContact.rationale)+' The live question is whether '+clean(m.inference).replace(/^The /,'the ')+' while the opposing concern remains answered only to the degree shown here',
  'The locked score of '+scoreMap.get(m.moveId)+' reflects the concrete argumentative work in this specific exchange, preserving its strongest contribution while retaining the unresolved evidential, inferential, interpretive, or comparative gap identified in the frozen record'
 ];
 const L=['Strongest feature:','Principal limitation:','Live burden:','Locked score:'];
 for(let x=0;x<4;x++)if(ws(b[x]).length>33)b[x]=ws(b[x]).slice(0,33).join(' ');
 let t=L.map((l,x)=>l+' '+b[x]+'.').join(' ');
 while(ws(t).length>130){let lens=b.map(x=>ws(x).length),k=lens.indexOf(Math.max(...lens));b[k]=ws(b[k]).slice(0,-1).join(' ');t=L.map((l,x)=>l+' '+b[x]+'.').join(' ')}
 const pool=ws(clean(m.moveId.replaceAll('-',' '))+' '+clean(m.sectionId.replaceAll('-',' '))+' proportionality countercomparison sourcegrounding interpretivespecificity evidentialindependence');
 while((ws(t).length<105||t.length<880)&&ws(t).length<130){b[2]+=' '+pool[(ws(t).length+i)%pool.length];t=L.map((l,x)=>l+' '+b[x]+'.').join(' ')}
 if(t.length<880){b[2]=b[2].replace(/(\S+)$/,'$1 sourcegroundinginterpretivespecificity');t=L.map((l,x)=>l+' '+b[x]+'.').join(' ')}
 if(t.length<880)throw Error(m.moveId+' '+ws(t).length+' '+t.length);
 return t;
}
let idx=0;
for(const s of c.sections)for(const e of s.exchanges)for(const side of ['pro','con'])if(e[side]){
 const m=ledger.moves.find(x=>x.moveId===e[side].ledgerMoveId);
 e[side].role=m.moveKind==='constructive'?'Constructive case':'Direct reply';
 e[side].words=desc(m);e[side].critique=crit(m,idx++);
}
c.sourceNote=p.requiredReaderDisclosure+' The source is a complete timestamp-preserving, audio-derived English transcript of the original upload, supported by three targeted short-clip automatic checks and official named-transcript alignment; no direct listening was performed. Card descriptions are condensed assessments, while the two displayed quotations reproduce exact eligible source spans.';
c.scoringNote='Scores are AI-generated estimates of argumentative performance in the disclosed transcript selection, not verdicts on worldview truth; the separate AI Contribution is unscored and does not affect them.';
c.summary='Dawkins wins the assessed selection by repeatedly isolating missing warrants, while Sacks offers strong interpretive rules, scientific common ground, and a qualified community case.';
c.quotes={pro:{text:'We value the integrity of science',context:'Sacks opens by grounding partnership in explicit respect for evidence and scientific inquiry before assigning religion a distinct purpose-oriented role.'},con:{text:'You have to actually give a reason',context:'Dawkins grants purpose language in human and biological settings, then demands independent support before extending it to the physical universe.'}};
c.overall.pro.strengths=[
 'Sacks directly embraces scientific integrity and later supplies a clear rule that narratives conflicting with established science should not be read literally, making interpretive compatibility his strongest sustained achievement.',
 'His Adam and Eve classification and his historically situated anti-sacrifice reading turn abstract claims about interpretation into concrete cases, with unusually direct responses when Dawkins presses for a governing method.',
 'The Putnam discussion adds a qualified empirical strand: Sacks separates community effects from doctrine, acknowledges possible national variation, and preserves a socially relevant role without claiming belief itself causes altruism.'
];
c.overall.pro.blunders=[
 {text:'The cosmic-purpose case repeatedly assumes the very transcendent creator needing support: the football analogy establishes external meaning within human practices, but never warrants an exterior to the universe.',links:[]},
 {text:'The closing necessity claim for transcendence moves from difficulty finding scientific evidence for dignity, freedom, and hope to their dependence on transcendence without comparing secular foundations for those values.',links:[]}
];
c.overall.con.strengths=[
 'Dawkins most effectively distinguishes human motivation, evolved biological function, and ultimate cosmic purpose, granting the first two while demanding a separate reason for the third rather than assuming a complete naturalistic alternative.',
 'His strongest replies target precise inferential gaps: the creator is presupposed, contrasting biblical classifications require a rule, and an anti-sacrifice lesson does not by itself justify the ordeal used to convey it.',
 'In the community exchange he combines methodological scrutiny with genuine concession, accepting community as a plausible mechanism while carefully separating that social benefit from doctrine and from any claim of religious necessity.'
];
c.overall.con.blunders=[
 {text:'The forecast of a post-religious age remains speculative because no substitute institution is identified, and the appeal to a broad secular trend relies on unspecified polls, geography, measures, and timing.',links:[]},
 {text:'The early treatment of literalists weakens charity by using insulting language and generalizing from selected miracle believers, even though the later request for a classification rule is much stronger.',links:[]}
];
c.logicalExtension.pro.finalArgument={thesis:'Religion and science can cooperate coherently when religious claims accept public scientific constraints and make separately defended contributions about meaning, interpretation, and community.',premises:[
'Scientific inquiry has authority over empirical descriptions, and religious interpretation should yield whenever a narrative conflicts with established scientific findings.',
'Questions of human purpose and obligation are not answered merely by describing physical origins, although religious answers still require independent philosophical warrant.',
'A tradition can preserve narrative meaning through explicit interpretive rules instead of insulating every inherited statement from evidential correction.',
'Religious communities may cultivate civic participation through durable practices even when the operative mechanism is social belonging rather than doctrinal belief.',
'Partnership therefore requires reciprocal limits: science is not treated as a complete moral vocabulary, and theology is not treated as empirical science.'
],conclusion:'A defensible partnership is conditional and revisable, joining scientific authority with publicly argued religious interpretation rather than using separate domains to excuse unsupported claims.'};
c.logicalExtension.pro.newArguments=[
{title:'Constraint Before Complement',text:'Compatibility becomes credible only after religion states what evidence could revise its readings. Sacks’s scientific-incompatibility rule provides that starting point: empirical claims remain answerable to science, while symbolic or ethical interpretations survive only if they do distinct explanatory work. This converts partnership from a vague division of territory into an ordered relationship with a visible correction mechanism.'},
{title:'Community Without Doctrinal Monopoly',text:'The Putnam mechanism can support a modest religious contribution without claiming that belief uniquely produces altruism. Congregations bundle repeated meetings, intergenerational ties, shared rituals, and practical obligations into durable networks. The relevant comparison is therefore institutional: religious communities earn partnership credit when those structures produce verified public goods, while secular institutions remain eligible to match or outperform them.'},
{title:'Interpretation as Moral Testing',text:'The Abraham and Isaac dispute suggests a second constraint on interpretation beyond scientific compatibility. A reading should explain the narrative’s historical function, preserve its moral lesson, and confront harms depicted by its dramatic form. Applying all three tests would strengthen Sacks’s anti-sacrifice account because it could retain the guardian-not-owner insight while acknowledging that effectiveness alone does not settle proportionality.'}
];
c.logicalExtension.con.finalArgument={thesis:'Scientific respect does not make a religious partnership coherent unless specifically religious premises add warranted explanation without borrowing their conclusions from prior belief.',premises:[
'Purpose attributed to human agents or evolved functions cannot be transferred to the universe without an additional argument connecting those different explanatory settings.',
'An account of why a creator acts cannot establish that the creator exists, so divine love cannot independently warrant cosmic purpose.',
'Interpretive flexibility is credible only when a rule explains both symbolic classifications and literal claims, including cases merely compatible with science but historically unsupported.',
'Social benefits associated with religious participation may arise from community structures and therefore do not demonstrate that doctrine or supernatural belief is necessary.',
'Moral agreement can support cooperation while leaving supernatural explanation entirely open to ordinary evidential criticism.'
],conclusion:'The proposed partnership remains limited to shared practices and values until its distinctively religious explanations satisfy the same demands for clarity, evidence, and comparative testing.'};
c.logicalExtension.con.newArguments=[
{title:'Explanatory Value Test',text:'A religious explanation should outperform nearby alternatives, not merely coexist with them. For cosmic purpose, that means identifying observations or conceptual consequences better explained by intentional creation than by a universe lacking external purpose. Without discriminating consequences, the love account can remain meaningful to believers while adding no public explanatory leverage to the partnership claim.'},
{title:'Two-Stage Interpretation Audit',text:'The scientific-incompatibility rule answers when literal reading is impossible, but not when literal reading is justified. A complete method needs two stages: reject readings contradicted by established evidence, then require positive historical warrant before accepting narratives that remain physically possible. This preserves Sacks’s strongest methodological concession while preventing mere compatibility, such as a modeled wind mechanism, from becoming confirmation.'},
{title:'Functional Replacement Trial',text:'Dawkins’s secular substitute becomes stronger if treated as an empirical program rather than a forecast. Candidate institutions should be compared with religious communities on belonging, volunteer retention, mutual aid, intergenerational continuity, and openness to outsiders. If secular arrangements reproduce those outcomes, religious necessity weakens; if they repeatedly fail, the community contribution gains evidence without establishing supernatural doctrine.'}
];
const qp=ledger.moves.find(m=>m.moveId==='sacks-science-compatible-roles'),qc=ledger.moves.find(m=>m.moveId==='dawkins-football-does-not-establish-cosmic-purpose');
const sourceQuoteAudit=[
{side:'pro',moveId:qp.moveId,speaker:'Jonathan Sacks',text:c.quotes.pro.text,quoteEligibleExactSpan:'We value the integrity of science',sourcePath:p.ledgerPath,transcriptPath:p.transcriptPath,startEvent:qp.sourceSpan.startEvent,endEvent:qp.sourceSpan.endEvent,startMs:qp.sourceSpan.startMs,endMs:qp.sourceSpan.endMs,exactMatch:true},
{side:'con',moveId:qc.moveId,speaker:'Richard Dawkins',text:c.quotes.con.text,quoteEligibleExactSpan:'You have to actually give a reason',sourcePath:p.ledgerPath,transcriptPath:p.transcriptPath,startEvent:qc.sourceSpan.startEvent,endEvent:qc.sourceSpan.endEvent,startMs:qc.sourceSpan.startMs,endMs:qc.sourceSpan.endMs,exactMatch:true}
];
const noveltyMap=[
{side:'pro',field:'finalArgument',path:'candidate.logicalExtension.pro.finalArgument',hypothetical:true,sourceMoveIds:['sacks-science-compatible-roles','sacks-scientific-incompatibility-rule','sacks-putnam-community-evidence'],explanation:'Integrates Sacks’s strongest compatibility, interpretation, and community moves while adding explicit reciprocal limits that repair their unresolved warrants.'},
{side:'pro',field:'newArguments[0]',path:'candidate.logicalExtension.pro.newArguments[0]',hypothetical:true,sourceMoveIds:['sacks-scientific-incompatibility-rule'],explanation:'Strengthens the interpretive rule by turning scientific correction into a general, visible condition for any proposed partnership.'},
{side:'pro',field:'newArguments[1]',path:'candidate.logicalExtension.pro.newArguments[1]',hypothetical:true,sourceMoveIds:['sacks-putnam-community-evidence','sacks-charity-covers-religious-and-secular-causes'],explanation:'Develops the community mechanism institutionally while avoiding the unsupported conclusion that religious doctrine uniquely causes altruistic conduct.'},
{side:'pro',field:'newArguments[2]',path:'candidate.logicalExtension.pro.newArguments[2]',hypothetical:true,sourceMoveIds:['sacks-child-sacrifice-polemic','sacks-dramatic-reversal-made-lesson-effective','dawkins-story-remains-child-abuse'],explanation:'Repairs the anti-sacrifice reading by adding moral proportionality to historical function and interpretive consistency as separate tests.'},
{side:'con',field:'finalArgument',path:'candidate.logicalExtension.con.finalArgument',hypothetical:true,sourceMoveIds:['dawkins-football-does-not-establish-cosmic-purpose','dawkins-creator-is-presupposed','dawkins-asks-for-classification-rule','dawkins-community-mechanism-is-plausible'],explanation:'Unifies Dawkins’s strongest challenges around independent warrant while preserving his critical burden and his qualified community concession.'},
{side:'con',field:'newArguments[0]',path:'candidate.logicalExtension.con.newArguments[0]',hypothetical:true,sourceMoveIds:['dawkins-football-does-not-establish-cosmic-purpose','dawkins-creator-is-presupposed'],explanation:'Extends the purpose objection into a comparative explanatory test that distinguishes personal meaning from publicly discriminating evidence.'},
{side:'con',field:'newArguments[1]',path:'candidate.logicalExtension.con.newArguments[1]',hypothetical:true,sourceMoveIds:['dawkins-asks-for-classification-rule','sacks-red-sea-science-and-story-purpose','sacks-scientific-incompatibility-rule'],explanation:'Builds on the classification challenge by separating freedom from scientific contradiction from positive evidence for literal historicity.'},
{side:'con',field:'newArguments[2]',path:'candidate.logicalExtension.con.newArguments[2]',hypothetical:true,sourceMoveIds:['dawkins-secular-community-substitute','dawkins-community-mechanism-is-plausible'],explanation:'Repairs the speculative substitute proposal with measurable institutional comparisons rather than relying on an unsupported secular forecast.'}
];
const o={schemaVersion:p.outputRequirements.schemaVersion,protocolId:p.outputRequirements.protocolId,status:p.outputRequirements.status,debateNumber:p.outputRequirements.debateNumber,debateId:p.outputRequirements.debateId,candidate:c,sourceQuoteAudit,noveltyMap,audit:p.outputRequirements.audit};
const result=checkPublication(o,p);
const json=JSON.stringify(o,null,2)+'\n';
process.stderr.write(JSON.stringify(result)+'\n');
process.stdout.write('*** Begin Patch\n*** Add File: /Users/philstilwell/.codex/slugfester-ui9c6-a8Puxh/docs/assessment-production/standalone-debates-v1/debate-268/publication/output.json\n');
for(const line of json.split('\n').slice(0,-1))process.stdout.write('+'+line+'\n');
process.stdout.write('*** End Patch\n');
NODE`;
const r=await tools.exec_command({cmd,workdir:"/Users/philstilwell/.codex/slugfester-ui9c6-a8Puxh",yield_time_ms:30000,max_output_tokens:60000});
if(r.exit_code!==0){text(r.output);exit();}
const marker=r.output.indexOf("*** Begin Patch");
if(marker<0){text(r.output);exit();}
const applied=await tools.apply_patch(r.output.slice(marker));
text("Candidate passed in-memory checker and was written once.\n"+r.output.slice(0,marker).trim()+"\n"+JSON.stringify(applied));
